import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:provider/provider.dart';
import 'package:intl/date_symbol_data_local.dart';
import 'package:firebase_core/firebase_core.dart';

// Firebase Options generated by flutterfire configure
import 'firebase_options.dart';

// Project Imports
import 'core/services/notification_service.dart';
import 'core/theme/app_theme.dart';
import 'features/home/presentation/widgets/main_navigation.dart';
import 'features/auth/data/providers/auth_provider.dart';
import 'features/auth/presentation/pages/login_screen.dart';
import 'features/auth/presentation/pages/register_screen.dart';
import 'features/auth/presentation/pages/pending_approval_screen.dart';

// Global navigation key used for routing without BuildContext
final GlobalKey<NavigatorState> navigatorKey = GlobalKey<NavigatorState>();

void main() async {
  WidgetsFlutterBinding.ensureInitialized();

  const Color scaffoldBgColor = Color(0xFFF5F5F5);

  // Logic: Forcing Full Immersion / Edge-to-Edge mode
  SystemChrome.setSystemUIOverlayStyle(const SystemUiOverlayStyle(
    statusBarColor: Colors.transparent, // Technical: Makes status bar transparent
    statusBarIconBrightness: Brightness.light, // UI/UX: Icons adjusted for light surface
    systemNavigationBarColor: scaffoldBgColor, // Technical: Modern navigation surface
    systemNavigationBarIconBrightness: Brightness.dark,
    systemNavigationBarDividerColor: scaffoldBgColor,
  ));

  await SystemChrome.setEnabledSystemUIMode(SystemUiMode.edgeToEdge);

  // Logic: Standard cross-platform initialization using FirebaseOptions
  await Firebase.initializeApp(
    options: DefaultFirebaseOptions.currentPlatform,
  );

  await NotificationService().initialize();

  // Logic: Syncing internationalization for Portuguese date formats
  await initializeDateFormatting('pt_BR', null);

  runApp(
    // Technical: Context management for Auth and Roles
    ChangeNotifierProvider(
      create: (_) => AuthProvider(),
      child: const KinCareApp(),
    ),
  );
}

class KinCareApp extends StatelessWidget {
  const KinCareApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      navigatorKey: navigatorKey,
      title: 'KinCare',
      debugShowCheckedModeBanner: false,
      theme: AppTheme.lightTheme,
      // Technical: Initial entry point handles session resolution
      home: const AuthWrapper(),
      // Logic: Explicit route table for direct hash navigation and pushNamed
      routes: {
        '/login': (context) => const LoginScreen(),
        '/register': (context) => const RegisterScreen(),
        '/orders': (context) => const AuthWrapper(targetRoute: '/orders'),
        '/stock': (context) => const AuthWrapper(targetRoute: '/stock'),
        '/account': (context) => const AuthWrapper(targetRoute: '/account'),
      },
    );
  }
}

// Logic: Route Guard - Decides the first screen the user sees
class AuthWrapper extends StatelessWidget {
  final String? targetRoute;

  const AuthWrapper({super.key, this.targetRoute});

  @override
  Widget build(BuildContext context) {
    // Technical: Reactive listener to the AuthProvider state
    final authProvider = context.watch<AuthProvider>();

    // Step 1: Handle loading state (prevents "white screen" feedback gap)
    if (authProvider.isLoading) {
      return const Scaffold(
        body: Center(
          child: CircularProgressIndicator(
            valueColor: AlwaysStoppedAnimation<Color>(KinColors.primary),
          ),
        ),
      );
    }

    // Step 2: Security Gate - If no user is logged in, force LoginScreen
    if (authProvider.user == null) {
      return const LoginScreen();
    }

    // Step 2.5: If the profile has not loaded yet, or the role is 'pending', block execution here
    final role = authProvider.userProfile?['role'];
    if (role == 'pending') {
      return const PendingApprovalScreen();
    }

    // Step 3: Success - Mount MainNavigation starting at the target tab
    return MainNavigation(initialRoute: targetRoute);
  }
}